def is_prime(number):
    if number < 2:
        return False
    return all(number % divisor for divisor in range(2, math.isqrt(number)+1))
def is_perfect(number):
    if number <= 1:
        return False
    return sum(divisor for divisor in range(1, number) if number % divisor == 0) == number
assert not any(is_prime(n) for n in [-3, 0, 1, 4])
assert all(is_prime(n) for n in [2, 3, 7])
assert not any(is_perfect(n) for n in [-1, 0, 1, 7])
assert all(is_perfect(n) for n in [6, 28])
print('Простые до 15:', [n for n in range(15) if is_prime(n)])
print('Совершенные до 30:', [n for n in range(30) if is_perfect(n)])
